import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# ---------- Scalar scaling kernel ----------
scale_kernel_src = """
__global__ void scale_kernel(const float* a, float* out, const float factor, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] * factor;
    }
}
"""

# ---------- Elementwise division by scalar ----------
elementwise_div_cuda_src = """
torch::Tensor elementwise_div_cuda(torch::Tensor a, float scalar) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    scale_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), out.data_ptr<float()>, scalar, size);

    return out;
}
"""

elementwise_div_cpp_src = (
    "torch::Tensor elementwise_div_cuda(torch::Tensor a, float scalar);"
)

elementwise_div = load_inline(
    name="elementwise_div",
    cpp_sources=elementwise_div_cpp_src,
    cuda_sources=elementwise_div_cuda_src,
    functions=["elementwise_div_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.elementwise_div = elementwise_div

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        norm = torch.norm(x, p='fro').item()
        if norm == 0:
            return x
        return self.elementwise_div.elementwise_div_cuda(x, 1.0 / norm)
